import 'package:flutter/material.dart';
import '../../shared/tokens/tokens.dart';
import '../models/lab_student_record.dart';

/// جدول وقائمة كشف حضور المعمل التفاعلية (Lab Roster Table & List)
class LabRosterTable extends StatelessWidget {
  final List<LabStudentRecord> students;
  final Function(LabStudentRecord student, String newState) onStateChange;
  final Function(LabStudentRecord student)? onReviewException;

  const LabRosterTable({
    super.key,
    required this.students,
    required this.onStateChange,
    this.onReviewException,
  });

  @override
  Widget build(BuildContext context) {
    if (students.isEmpty) {
      return Container(
        padding: AppSpacing.paddingXL,
        alignment: Alignment.center,
        decoration: BoxDecoration(
          color: AppColors.surface,
          borderRadius: BorderRadius.circular(AppRadius.radiusMD),
          border: Border.all(color: AppColors.border),
        ),
        child: const Column(
          children: [
            Icon(Icons.people_outline_rounded, size: 48.0, color: AppColors.textSecondary),
            AppSpacing.gapVerticalMD,
            Text(\n              'لا يوجد طلاب مطابقين لمعايير البحث الحالية',\n              style: TextStyle(color: AppColors.textSecondary),\n            ),\n          ],\n        ),\n      );\n    }\n\n    return ListView.separated(\n      shrinkWrap: true,\n      physics: const NeverScrollableScrollPhysics(),\n      itemCount: students.length,\n      separatorBuilder: (_, __) => const SizedBox(height: 8.0),\n      itemBuilder: (context, index) {\n        final student = students[index];\n        return _buildStudentTile(context, student);\n      },\n    );\n  }\n\n  Widget _buildStudentTile(BuildContext context, LabStudentRecord student) {\n    final theme = Theme.of(context);\n\n    Color stateColor;\n    Color stateBg;\n    switch (student.attendanceState.toUpperCase()) {\n      case 'PRESENT':\n        stateColor = AppColors.success;\n        stateBg = AppColors.success.withValues(alpha: 0.12);\n        break;\n      case 'LATE':\n        stateColor = AppColors.warning;\n        stateBg = AppColors.warning.withValues(alpha: 0.12);\n        break;\n      case 'EXCUSED':\n        stateColor = const Color(0xFF0284C7);\n        stateBg = const Color(0xFF0284C7).withValues(alpha: 0.12);\n        break;\n      case 'ABSENT':\n      default:\n        stateColor = AppColors.error;\n        stateBg = AppColors.error.withValues(alpha: 0.12);\n    }\n\n    return Container(\n      padding: AppSpacing.paddingMD,\n      decoration: BoxDecoration(\n        color: AppColors.surface,\n        borderRadius: BorderRadius.circular(AppRadius.radiusMD),\n        border: Border.all(\n          color: student.hasPendingException ? AppColors.warning : AppColors.border,\n          width: student.hasPendingException ? 1.5 : 1.0,\n        ),\n      ),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          // الصف الأول: الاسم والرقم وشارة الحالة الحالية\n          Row(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              CircleAvatar(\n                radius: 18.0,\n                backgroundColor: stateBg,\n                child: Text(\n                  student.fullName.isNotEmpty ? student.fullName.characters.first : 'ط',\n                  style: TextStyle(\n                    color: stateColor,\n                    fontWeight: FontWeight.w700,\n                    fontSize: 14.0,\n                  ),\n                ),\n              ),\n              AppSpacing.gapHorizontalMD,\n              Expanded(\n                child: Column(\n                  crossAxisAlignment: CrossAxisAlignment.start,\n                  children: [\n                    Text(\n                      student.fullName,\n                      style: theme.textTheme.titleSmall?.copyWith(\n                        fontWeight: FontWeight.w700,\n                      ),\n                    ),\n                    const SizedBox(height: 2.0),\n                    Row(\n                      children: [\n                        Text(\n                          student.studentNumber,\n                          style: const TextStyle(\n                            fontSize: 11.5,\n                            color: AppColors.primary,\n                            fontWeight: FontWeight.w600,\n                          ),\n                        ),\n                        const SizedBox(width: 6.0),\n                        Text(\n                          '| ${student.departmentName}',\n                          style: const TextStyle(\n                            fontSize: 11.5,\n                            color: AppColors.textSecondary,\n                          ),\n                        ),\n                      ],\n                    ),\n                  ],\n                ),\n              ),\n              // شارة الحالة\n              Container(\n                padding: const EdgeInsets.symmetric(horizontal: 8.0, vertical: 3.0),\n                decoration: BoxDecoration(\n                  color: stateBg,\n                  borderRadius: BorderRadius.circular(AppRadius.radiusSM),\n                ),\n                child: Text(\n                  student.stateArabic,\n                  style: TextStyle(\n                    color: stateColor,\n                    fontWeight: FontWeight.w700,\n                    fontSize: 11.5,\n                  ),\n                ),\n              ),\n            ],\n          ),\n          // تنبيه الاستثناء المعلق إن وجد\n          if (student.hasPendingException) ...[\n            const SizedBox(height: 8.0),\n            Container(\n              padding: const EdgeInsets.symmetric(horizontal: 10.0, vertical: 6.0),\n              decoration: BoxDecoration(\n                color: const Color(0xFFFFFBEB),\n                borderRadius: BorderRadius.circular(AppRadius.radiusSM),\n                border: Border.all(color: const Color(0xFFFDE68A)),\n              ),\n              child: Row(\n                children: [\n                  const Icon(Icons.warning_amber_rounded, size: 14.0, color: Color(0xFFD97706)),\n                  const SizedBox(width: 6.0),\n                  Expanded(\n                    child: Text(\n                      'طلب استثناء: ${student.manualReason ?? \"عذر معلق\"}',\n                      style: const TextStyle(\n                        fontSize: 11.0,\n                        color: Color(0xFF92400E),\n                        fontWeight: FontWeight.w600,\n                      ),\n                      maxLines: 1,\n                      overflow: TextOverflow.ellipsis,\n                    ),\n                  ),\n                  if (onReviewException != null)\n                    InkWell(\n                      onTap: () => onReviewException!(student),\n                      child: const Text(\n                        'مراجعة واتخاذ قرار',\n                        style: TextStyle(\n                          fontSize: 11.0,\n                          color: AppColors.primary,\n                          fontWeight: FontWeight.w700,\n                          decoration: TextDecoration.underline,\n                        ),\n                      ),\n                    ),\n                ],\n              ),\n            ),\n          ],\n          AppSpacing.gapVerticalSM,\n          const Divider(color: AppColors.border, height: 1.0),\n          const SizedBox(height: 6.0),\n          // الصف السفلي: أزرار التبديل السريع لحالة حضور الطالب\n          Row(\n            mainAxisAlignment: MainAxisAlignment.spaceBetween,\n            children: [\n              const Text(\n                'تغيير الحالة:',\n                style: TextStyle(fontSize: 11.0, color: AppColors.textSecondary),\n              ),\n              Row(\n                mainAxisSize: MainAxisSize.min,\n                children: [\n                  _buildQuickActionButton(\n                    label: 'حاضر',\n                    isSelected: student.isPresent,\n                    color: AppColors.success,\n                    onTap: () => onStateChange(student, 'PRESENT'),\n                  ),\n                  const SizedBox(width: 4.0),\n                  _buildQuickActionButton(\n                    label: 'متأخر',\n                    isSelected: student.isLate,\n                    color: AppColors.warning,\n                    onTap: () => onStateChange(student, 'LATE'),\n                  ),\n                  const SizedBox(width: 4.0),\n                  _buildQuickActionButton(\n                    label: 'معذور',\n                    isSelected: student.isExcused,\n                    color: const Color(0xFF0284C7),\n                    onTap: () => onStateChange(student, 'EXCUSED'),\n                  ),\n                  const SizedBox(width: 4.0),\n                  _buildQuickActionButton(\n                    label: 'غائب',\n                    isSelected: student.isAbsent,\n                    color: AppColors.error,\n                    onTap: () => onStateChange(student, 'ABSENT'),\n                  ),\n                ],\n              ),\n            ],\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildQuickActionButton({\n    required String label,\n    required bool isSelected,\n    required Color color,\n    required VoidCallback onTap,\n  }) {\n    return InkWell(\n      onTap: onTap,\n      borderRadius: BorderRadius.circular(AppRadius.radiusSM),\n      child: Container(\n        padding: const EdgeInsets.symmetric(horizontal: 8.0, vertical: 3.0),\n        decoration: BoxDecoration(\n          color: isSelected ? color : AppColors.surface,\n          borderRadius: BorderRadius.circular(AppRadius.radiusSM),\n          border: Border.all(\n            color: isSelected ? color : AppColors.border,\n            width: isSelected ? 1.2 : 0.8,\n          ),\n        ),\n        child: Text(\n          label,\n          style: TextStyle(\n            fontSize: 11.0,\n            fontWeight: isSelected ? FontWeight.w700 : FontWeight.w500,\n            color: isSelected ? Colors.white : AppColors.textSecondary,\n          ),\n        ),\n      ),\n    );\n  }\n}\n